export const groups=[{"id":"legs","title":"Ноги","count":18},{"id":"glutes","title":"Ягодицы","count":14},{"id":"back","title":"Спина","count":12},{"id":"chest","title":"Грудь","count":9},{"id":"shoulders","title":"Плечи","count":11},{"id":"arms","title":"Руки","count":13},{"id":"core","title":"Мышцы корпуса","count":10}];
export const exercises=[{"id":"legs01","group":"legs","title":"Приседание до стула","muscles":"Квадрицепсы · ягодицы","equipment":"Стул","level":"начальный","reps":"10–12","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Стойка и опора","Таз назад, мягкий присед","Подъём через всю стопу"],"steps":["Поставьте устойчивый стул позади себя, стопы — на ширине таза. Стул не должен скользить.","Отведите таз назад, согните колени по направлению носков и мягко коснитесь сиденья. Пятки остаются на полу.","На выдохе встаньте через всю стопу. Не падайте на сиденье и не отталкивайтесь рывком."],"cue":"Сначала найдите удобную высоту стула; глубина приседа не должна мешать сохранять опору.","easier":"Возьмите устойчивый стул повыше. Сядьте полностью, сделайте паузу и встаньте, слегка помогая ладонями на бёдрах.","advanced":false},{"id":"legs02","group":"legs","title":"Гоблет-присед с гантелью","muscles":"Квадрицепсы · ягодицы","equipment":"Гантель","level":"средний","reps":"8–12","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Стойка и опора","Таз назад, мягкий присед","Подъём через всю стопу"],"steps":["Встаньте устойчиво, держите одну гантель двумя руками у груди. Локти направлены вниз.","Отведите таз назад и согните колени по направлению носков. Гантель остаётся близко к груди.","Выдохните и встаньте через всю стопу, не отклоняя корпус назад."],"cue":"Приседайте только до той глубины, где пятки остаются на полу.","easier":"Уберите гантель и приседайте до устойчивого стула. Начните с неглубокого приседа.","advanced":false},{"id":"legs03","group":"legs","title":"Сумо-присед с гантелью","muscles":"Приводящие · ягодицы","equipment":"Гантель","level":"средний","reps":"10–12","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Стойка и опора","Таз назад, мягкий присед","Подъём через всю стопу"],"steps":["Поставьте стопы чуть шире плеч, носки немного наружу. Держите гантель двумя руками перед собой.","Плавно согните колени в направлении носков; гантель опускается между ногами.","Поднимитесь без рывка, сохраняя опору на всю стопу."],"cue":"Ширина стойки должна быть удобной для тазобедренных суставов.","easier":"Выполняйте без гантели и опускайтесь неглубоко. Не ставьте стопы шире, чем позволяет удобное положение коленей.","advanced":false},{"id":"legs04","group":"legs","title":"Выпад вперёд с опорой","muscles":"Квадрицепсы · ягодицы","equipment":"Стул","level":"средний","reps":"8–10","rest":60,"sets":2,"unit":"reps","unilateral":true,"phases":["Устойчивая стойка","Согните колени","Вернитесь в стойку"],"steps":["Встаньте рядом с устойчивой опорой и возьмитесь за неё одной рукой.","Шагните вперёд и неглубоко согните оба колена. Передняя стопа полностью на полу.","Оттолкнитесь передней стопой и вернитесь в стойку. Выполните повторы, затем смените ногу."],"cue":"Переднее колено движется в направлении носка, таз не разворачивается.","easier":"Оставьте стопы в положении шага и держитесь за опору. Сгибайте колени лишь немного, без шага вперёд.","advanced":false},{"id":"legs05","group":"legs","title":"Выпад назад","muscles":"Квадрицепсы · ягодицы","equipment":"Свой вес","level":"начальный","reps":"8–10","rest":60,"sets":2,"unit":"reps","unilateral":true,"phases":["Устойчивая стойка","Согните колени","Вернитесь в стойку"],"steps":["Встаньте устойчиво; при необходимости держитесь за неподвижную опору.","Шагните одной ногой назад и согните колени. Передняя пятка остаётся на полу.","Нажимая передней стопой на пол, верните заднюю ногу. После повторов смените сторону."],"cue":"Шагайте назад без падения на колено.","easier":"Держитесь за устойчивую опору и делайте короткий шаг назад с неглубоким сгибанием коленей.","advanced":false},{"id":"legs06","group":"legs","title":"Болгарский сплит-присед","muscles":"Квадрицепсы · ягодицы","equipment":"Низкая устойчивая опора","level":"сложный","reps":"6–8","rest":75,"sets":2,"unit":"reps","unilateral":true,"phases":["Устойчивая стойка","Согните колени","Вернитесь в стойку"],"steps":["Поставьте заднюю стопу на низкую устойчивую опору, переднюю — на пол. При необходимости держитесь за стену.","Согните переднее колено и опустите таз неглубоко, сохраняя переднюю стопу на полу.","Выпрямитесь без рывка. Выполните повторы и смените сторону."],"cue":"Сначала освойте тот же присед с задней стопой на полу.","easier":"Поставьте заднюю стопу на пол вместо возвышения. Держитесь за опору и выполняйте неглубокий сплит-присед.","advanced":true},{"id":"legs07","group":"legs","title":"Обратный выпад с гантелями","muscles":"Квадрицепсы · ягодицы","equipment":"Гантели","level":"средний","reps":"8–10","rest":75,"sets":2,"unit":"reps","unilateral":true,"phases":["Устойчивая стойка","Согните колени","Вернитесь в стойку"],"steps":["Встаньте с гантелями в опущенных руках. Корпус устойчив, плечи расслаблены.","Шагните одной ногой назад и неглубоко согните колени. Гантели остаются по сторонам тела.","Вернитесь усилием передней ноги. После повторов смените ногу."],"cue":"Если сложно держать равновесие, сначала уберите гантели и возьмитесь за опору.","easier":"Уберите гантели, придерживайтесь за опору и шагайте назад на удобное расстояние.","advanced":false},{"id":"legs08","group":"legs","title":"Присед на одной ноге с опорой","muscles":"Квадрицепсы · ягодицы","equipment":"Стул","level":"сложный","reps":"6–8","rest":75,"sets":2,"unit":"reps","unilateral":true,"phases":["Стойка и опора","Таз назад, мягкий присед","Подъём через всю стопу"],"steps":["Держитесь двумя руками за спинку устойчивого стула. Перенесите вес на одну ногу, вторую слегка вытяните вперёд.","Отведите таз назад и неглубоко согните опорное колено. Пятка остаётся на полу.","Выпрямите опорную ногу под контролем; после повторов смените сторону."],"cue":"Не тяните стул на себя. Начните с дополнительной опоры носком свободной ноги.","easier":"Оставьте носок свободной ноги на полу для поддержки. Держитесь за стул и приседайте неглубоко.","advanced":true},{"id":"legs09","group":"legs","title":"Подъём на носки стоя","muscles":"Икроножные · камбаловидные","equipment":"Стул","level":"начальный","reps":"12–15","rest":45,"sets":2,"unit":"reps","unilateral":false,"phases":["Пятки на полу","Поднимите пятки","Плавно опустите"],"steps":["Поставьте стопы параллельно и найдите опору.","Поднимайтесь на носки без завала стоп наружу.","Опустите пятки медленно, не пружиньте."],"cue":"Поднимайтесь на носки без завала стоп наружу.","easier":"Держитесь за спинку устойчивого стула двумя руками и поднимайте пятки невысоко. Обе ноги работают вместе.","advanced":false},{"id":"legs10","group":"legs","title":"Подъём пяток сидя","muscles":"Камбаловидные · икры","equipment":"Стул","level":"начальный","reps":"12–15","rest":45,"sets":2,"unit":"reps","unilateral":false,"phases":["Пятки на полу","Поднимите пятки","Плавно опустите"],"steps":["Сядьте на устойчивый стул, стопы параллельны, колени примерно над пятками.","Оставляя переднюю часть стоп на полу, плавно поднимите обе пятки.","Медленно опустите пятки и повторите без пружинящих движений."],"cue":"Бёдра остаются на сиденье, работают голеностопы.","easier":"Оставьте переднюю часть стоп на полу и поднимайте обе пятки всего на несколько сантиметров.","advanced":false},{"id":"legs11","group":"legs","title":"Румынская тяга с гантелями","muscles":"Задняя поверхность бедра · ягодицы","equipment":"Гантели","level":"средний","reps":"8–12","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Ровная стойка","Отведите таз назад","Выпрямитесь"],"steps":["Слегка согните колени, удлините спину.","Отведите таз назад, наклоняя прямой корпус и сохраняя гантели близко к ногам.","Напрягите ягодицы и выпрямитесь без переразгибания поясницы."],"cue":"Отведите таз назад, наклоняя прямой корпус и сохраняя гантели близко к ногам.","easier":"Уберите гантели, положите руки на таз и отводите его назад с небольшим наклоном корпуса.","advanced":false},{"id":"legs12","group":"legs","title":"Good morning без веса","muscles":"Задняя поверхность бедра · ягодицы","equipment":"Свой вес","level":"начальный","reps":"10–12","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Ровная стойка","Отведите таз назад","Выпрямитесь"],"steps":["Встаньте на ширине таза, положите ладони на таз и слегка смягчите колени.","Отведите таз назад и наклоните корпус от тазобедренных суставов. Спина сохраняет естественные изгибы.","Нажмите стопами на пол и вернитесь в стойку, не отклоняясь назад."],"cue":"Выполняйте без гантелей. Движение начинается тазом, а не округлением спины.","easier":"Встаньте спиной недалеко от стены и мягко коснитесь её тазом, слегка сгибая колени.","advanced":false},{"id":"legs13","group":"legs","title":"Сгибание ног лёжа","muscles":"Задняя поверхность бедра","equipment":"Коврик","level":"начальный","reps":"10–12","rest":45,"sets":2,"unit":"reps","unilateral":false,"phases":["Исходная опора","Согните колено","Верните ногу"],"steps":["Лягте на живот, ноги вытянуты. Можно опереться на предплечья, если пояснице удобно.","Плавно согните колени, направляя пятки к ягодицам. Таз остаётся на коврике.","Опустите голени под контролем и повторите."],"cue":"Не стремитесь коснуться ягодиц пятками и не усиливайте прогиб.","easier":"Сгибайте по одной ноге, оставляя вторую на коврике. Не тяните пятку до ягодицы.","advanced":false},{"id":"legs14","group":"legs","title":"Разгибание ноги сидя","muscles":"Квадрицепсы","equipment":"Стул","level":"начальный","reps":"10–12","rest":45,"sets":2,"unit":"reps","unilateral":true,"phases":["Сядьте ровно","Выпрямите колено","Опустите стопу"],"steps":["Сядьте на устойчивый стул, стопы на полу.","Выпрямите одну ногу до комфортного положения, не блокируя колено.","Плавно опустите стопу и повторите другой стороной."],"cue":"Выполняйте без незакреплённой гантели: здесь безопасный вариант со своим весом.","easier":"Разгибайте колено только наполовину. Бедро остаётся на сиденье, спина опирается на спинку.","advanced":false},{"id":"legs15","group":"legs","title":"Боковой выпад","muscles":"Квадрицепсы · приводящие · ягодицы","equipment":"Свой вес","level":"средний","reps":"8–10","rest":60,"sets":2,"unit":"reps","unilateral":true,"phases":["Широкая стойка","Сместите таз в сторону","Вернитесь в центр"],"steps":["Встаньте широко, стопы направлены вперёд или немного наружу.","Перенесите таз назад и в одну сторону, сгибая эту ногу. Другая нога остаётся почти прямой.","Оттолкнитесь всей стопой согнутой ноги и вернитесь в центр. Затем выполните другую сторону."],"cue":"Колено сгибаемой ноги направлено по носку; обе пятки остаются на полу.","easier":"Держитесь за опору и переносите вес из стороны в сторону без глубокого выпада.","advanced":false},{"id":"legs16","group":"legs","title":"Присед с паузой","muscles":"Квадрицепсы · ягодицы","equipment":"Свой вес","level":"средний","reps":"8–10","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Стойка и опора","Таз назад, мягкий присед","Подъём через всю стопу"],"steps":["Встаньте на ширине таза, руки вытяните вперёд.","Отведите таз назад и присядьте до удобной глубины. Остановитесь на 1–2 секунды, продолжая дышать.","Поднимитесь через всю стопу без рывка."],"cue":"Пауза короткая: не задерживайте дыхание.","easier":"Уберите паузу и выполняйте неглубокий присед до устойчивого стула.","advanced":false},{"id":"legs17","group":"legs","title":"Шаг на невысокую ступень","muscles":"Квадрицепсы · ягодицы","equipment":"Ступень","level":"средний","reps":"8–10","rest":60,"sets":2,"unit":"reps","unilateral":true,"phases":["Стопа на ступени","Поднимитесь вверх","Спуститесь под контролем"],"steps":["Используйте низкую устойчивую ступень, не сиденье стула.","Поднимитесь усилием верхней ноги, придерживаясь опоры.","Медленно спуститесь, сохраняя колено по направлению носка."],"cue":"Используйте низкую неподвижную ступень. На сиденье стула не вставайте.","easier":"Возьмите более низкую ступень и держитесь за перила. Стопа целиком помещается на ступени.","advanced":false},{"id":"legs18","group":"legs","title":"Подъём на носки с наклоном","muscles":"Икроножные","equipment":"Опора","level":"средний","reps":"12–15","rest":45,"sets":2,"unit":"reps","unilateral":false,"phases":["Пятки на полу","Поднимите пятки","Плавно опустите"],"steps":["Обопритесь ладонями о устойчивую поверхность и слегка наклоните корпус вперёд. Стопы параллельны.","Поднимите обе пятки, сохраняя опору на переднюю часть стоп.","Плавно опустите пятки без пружинящего движения."],"cue":"Опора неподвижна; наклон небольшой, поясница не прогибается.","easier":"Встаньте ровнее и держитесь за спинку стула. Поднимайте обе пятки невысоко.","advanced":false},{"id":"glutes01","group":"glutes","title":"Ягодичный мост","muscles":"Ягодицы · задняя поверхность бедра","equipment":"Коврик","level":"начальный","reps":"12–15","rest":45,"sets":2,"unit":"reps","unilateral":false,"phases":["Лягте и согните колени","Поднимите таз","Опустите таз"],"steps":["Лягте на спину, согните колени и поставьте стопы на ширине таза. Голова и плечи лежат на коврике.","Сожмите ягодицы и поднимите таз до линии плечи–таз–колени, не выгибая поясницу.","Плавно опустите таз на коврик и повторите."],"cue":"Подъём заканчивается за счёт ягодиц, а не прогиба в пояснице.","easier":"Поднимайте таз на несколько сантиметров, затем полностью опускайте на коврик. Обе стопы остаются на полу.","advanced":false},{"id":"glutes02","group":"glutes","title":"Ягодичный мост с гантелью","muscles":"Ягодицы · задняя поверхность бедра","equipment":"Гантель","level":"средний","reps":"10–12","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Лягте и согните колени","Поднимите таз","Опустите таз"],"steps":["Лягте на спину и согните колени. Положите гантель на складку таза через полотенце и придерживайте обеими руками.","Нажмите стопами в пол и поднимите таз без прогиба; гантель остаётся неподвижной.","Плавно опуститесь, продолжая удерживать гантель."],"cue":"Проверьте фиксаторы сборной гантели до начала.","easier":"Уберите гантель и выполняйте обычный ягодичный мост на двух ногах.","advanced":false},{"id":"glutes03","group":"glutes","title":"Мост на одной ноге","muscles":"Ягодицы · стабилизаторы таза","equipment":"Коврик","level":"сложный","reps":"8–10","rest":60,"sets":2,"unit":"reps","unilateral":true,"phases":["Лягте и согните колени","Поднимите таз","Опустите таз"],"steps":["Лягте на спину, одну стопу поставьте на пол, вторую ногу согните и поднимите над тазом. Голова и плечи лежат на коврике.","Нажимая опорной стопой, поднимите таз без перекоса и прогиба поясницы.","Плавно опуститесь; повторите другой ногой."],"cue":"Нажимая опорной стопой, поднимите таз без перекоса и прогиба поясницы.","easier":"Поставьте обе стопы на пол и поднимайте таз двумя ногами.","advanced":true},{"id":"glutes04","group":"glutes","title":"Мост со стопами на опоре","muscles":"Ягодицы · задняя поверхность бедра","equipment":"Ступень","level":"средний","reps":"10–12","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Лягте и согните колени","Поднимите таз","Опустите таз"],"steps":["Лягте на спину, поставьте обе стопы на низкую устойчивую опору. Голова и плечи лежат на коврике.","Напрягите ягодицы и поднимите таз до ровной линии корпуса. Опора не должна скользить.","Плавно верните таз на коврик, не переразгибая поясницу."],"cue":"Напрягите ягодицы и поднимите таз до ровной линии корпуса. Опора не должна скользить.","easier":"Уберите возвышение: поставьте обе стопы на пол и выполняйте обычный мост.","advanced":false},{"id":"glutes05","group":"glutes","title":"Отведение ноги назад стоя","muscles":"Ягодицы","equipment":"Стул","level":"начальный","reps":"10–12","rest":45,"sets":2,"unit":"reps","unilateral":true,"phases":["Встаньте у опоры","Отведите ногу назад","Верните стопу"],"steps":["Встаньте боком к устойчивой опоре и слегка согните опорную ногу.","Отведите другую ногу немного назад, не прогибая поясницу и не разворачивая таз.","Верните ногу и повторите; затем смените сторону."],"cue":"Отведите другую ногу немного назад, не прогибая поясницу и не разворачивая таз.","easier":"Держитесь двумя руками за опору и скользите носком назад по полу, не поднимая ногу.","advanced":false},{"id":"glutes06","group":"glutes","title":"Отведение ноги в сторону","muscles":"Средняя ягодичная","equipment":"Стул","level":"начальный","reps":"10–12","rest":45,"sets":2,"unit":"reps","unilateral":true,"phases":["Подготовьте опору","Отведите ногу в сторону","Верните ногу"],"steps":["Встаньте у устойчивого стула и придерживайтесь за спинку. Опорное колено слегка мягкое.","Отведите другую ногу в сторону невысоко. Носок смотрит вперёд, таз и корпус не наклоняются.","Верните стопу под таз. Выполните повторы и смените сторону."],"cue":"Небольшое отведение с ровным тазом полезнее высокого маха.","easier":"Держитесь за спинку стула двумя руками. Отводите носок в сторону по полу, сохраняя таз ровным.","advanced":false},{"id":"glutes07","group":"glutes","title":"Пожарный гидрант","muscles":"Средняя ягодичная","equipment":"Коврик","level":"начальный","reps":"10–12","rest":45,"sets":2,"unit":"reps","unilateral":true,"phases":["Опора на четвереньках","Откройте колено в сторону","Верните колено"],"steps":["Встаньте на четвереньки: ладони под плечами, колени под тазом.","Сохраняя колено согнутым, отведите одну ногу в сторону без поворота таза.","Плавно верните колено под таз. После повторов смените ногу."],"cue":"Не переносите весь вес на противоположную руку.","easier":"Отводите согнутое колено совсем немного и сразу возвращайте под таз. Корпус не поворачивается.","advanced":false},{"id":"glutes08","group":"glutes","title":"Разгибание ноги на четвереньках","muscles":"Большая ягодичная · задняя поверхность бедра","equipment":"Коврик","level":"начальный","reps":"10–12","rest":45,"sets":2,"unit":"reps","unilateral":true,"phases":["Устойчивая опора","Отведите ногу","Верните без рывка"],"steps":["Встаньте на четвереньки, ладони под плечами, колени под тазом.","Выпрямите одну ногу назад и поднимите не выше линии корпуса.","Верните колено на коврик без рывка; после повторов смените сторону."],"cue":"Поясница и таз остаются неподвижными.","easier":"Скользите носком назад по коврику, выпрямляя ногу без подъёма.","advanced":false},{"id":"glutes09","group":"glutes","title":"Боковая планка с подъёмом ноги","muscles":"Средняя ягодичная · косые мышцы","equipment":"Коврик","level":"сложный","reps":"6–8","rest":60,"sets":2,"unit":"reps","unilateral":true,"phases":["Боковая опора с колена","Поднимите верхнюю ногу","Опустите ногу"],"steps":["Лягте на бок с опорой на предплечье и согнутое нижнее колено. Локоть под плечом.","Поднимите таз и отведите прямую верхнюю ногу немного вверх, сохраняя корпус на боку.","Опустите верхнюю ногу под контролем. Завершите подход и смените сторону."],"cue":"Поднимите таз и отведите прямую верхнюю ногу немного вверх, сохраняя корпус на боку.","easier":"Оставьте таз на коврике и поднимайте верхнюю ногу лёжа на боку, без боковой планки.","advanced":true},{"id":"glutes10","group":"glutes","title":"Ракушка лёжа на боку","muscles":"Средняя ягодичная","equipment":"Коврик","level":"начальный","reps":"12–15","rest":45,"sets":2,"unit":"reps","unilateral":true,"phases":["Лягте на бок","Откройте верхнее колено","Закройте колено"],"steps":["Лягте на бок, согните колени, стопы вместе.","Поднимите верхнее колено без разворота таза назад.","Медленно опустите колено, сохраняя стопы вместе."],"cue":"Поднимите верхнее колено без разворота таза назад.","easier":"Открывайте верхнее колено на несколько сантиметров. Под голову положите сложенное полотенце.","advanced":false},{"id":"glutes11","group":"glutes","title":"Мост с отведением колена","muscles":"Ягодицы · стабилизаторы таза","equipment":"Коврик","level":"средний","reps":"8–10","rest":60,"sets":2,"unit":"reps","unilateral":true,"phases":["Поднимите таз","Мягко откройте колено","Верните колено"],"steps":["Лягте на спину, колени согнуты, стопы на полу. Поднимите таз в ягодичный мост.","Удерживая таз ровно, немного отведите одно колено в сторону. Стопа остаётся на полу.","Верните колено, затем повторите другой ногой. Не разворачивайте таз и не прогибайтесь."],"cue":"Удерживая таз ровно, немного отведите одно колено в сторону. Стопа остаётся на полу.","easier":"Оставьте таз на коврике и мягко отводите одно колено в сторону, не отрывая стопу.","advanced":false,"alternating":true},{"id":"glutes12","group":"glutes","title":"Donkey kicks с согнутой ногой","muscles":"Большая ягодичная","equipment":"Коврик","level":"начальный","reps":"10–12","rest":45,"sets":2,"unit":"reps","unilateral":true,"phases":["Устойчивая опора","Отведите ногу","Верните без рывка"],"steps":["Встаньте на четвереньки, слегка напрягите живот.","Оставляя колено согнутым примерно под прямым углом, отведите бедро назад и немного вверх.","Верните колено под таз. Повторите и смените сторону."],"cue":"Не поднимайте бедро выше спины и не запрокидывайте голову.","easier":"Отводите согнутое колено лишь немного назад, не поднимая бедро до уровня спины.","advanced":false},{"id":"glutes13","group":"glutes","title":"Frog pumps","muscles":"Ягодицы","equipment":"Коврик","level":"средний","reps":"12–15","rest":45,"sets":2,"unit":"reps","unilateral":false,"phases":["Лягте и согните колени","Поднимите таз","Опустите таз"],"steps":["Лягте на спину, соедините подошвы стоп и мягко раскройте колени. Голова и плечи на коврике.","Надавите внешним краем стоп на пол и слегка поднимите таз за счёт ягодиц.","Плавно опустите таз. Не разводите колени через усилие и не прогибайте поясницу."],"cue":"Надавите внешним краем стоп на пол и слегка поднимите таз за счёт ягодиц.","easier":"Поставьте стопы параллельно на пол и выполняйте обычный ягодичный мост.","advanced":false},{"id":"glutes14","group":"glutes","title":"Hip thrust с опорой под спину","muscles":"Ягодицы · задняя поверхность бедра","equipment":"Устойчивая опора","level":"средний","reps":"10–12","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Лопатки на опоре","Поднимите таз","Плавно опуститесь"],"steps":["Уприте устойчивую низкую скамью в стену. Расположите на её краю нижнюю часть лопаток, стопы на полу, колени согнуты.","Сожмите ягодицы и поднимите таз до линии плечи–таз–колени. Подбородок слегка направлен к груди.","Плавно опустите таз. При ненадёжной опоре выполняйте обычный мост на полу."],"cue":"Сожмите ягодицы и поднимите таз до линии плечи–таз–колени. Подбородок слегка направлен к груди.","easier":"Перенесите упражнение на пол: голова и плечи на коврике, обе стопы на полу — обычный мост.","advanced":false},{"id":"back01","group":"back","title":"Тяга гантели с опорой","muscles":"Широчайшие · бицепс","equipment":"Гантель и стул","level":"начальный","reps":"10–12","rest":60,"sets":2,"unit":"reps","unilateral":true,"phases":["Наклон и опора","Тяга к тазу","Контроль опускания"],"steps":["Поставьте одну ладонь на устойчивый стул, слегка согните колени и наклонитесь от таза. Гантель в свободной руке висит под плечом.","Ведите локоть к тазу, поднимая гантель близко к телу. Корпус не поворачивается.","Медленно опустите гантель. После повторов смените руку и опору."],"cue":"Смотрите в пол перед собой, сохраняя шею продолжением спины.","easier":"Снимите часть дисков с гантели. Свободной рукой прочно обопритесь на устойчивый стул и тяните без разворота корпуса.","advanced":false},{"id":"back02","group":"back","title":"Тяга двух гантелей в наклоне","muscles":"Широчайшие · ромбовидные","equipment":"Гантели","level":"средний","reps":"8–12","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Наклон и опора","Тяга к тазу","Контроль опускания"],"steps":["Возьмите две гантели, слегка согните колени и наклонитесь от таза. Руки направлены к полу.","Подтяните оба локтя к тазу, удерживая корпус неподвижным.","Медленно опустите обе гантели, не округляя спину."],"cue":"Не распрямляйте корпус, чтобы помочь гантелям подняться.","easier":"Выполняйте тягу одной рукой, а другой обопритесь на устойчивую поверхность.","advanced":false},{"id":"back03","group":"back","title":"Тяга гантелей к поясу сидя","muscles":"Широчайшие · ромбовидные","equipment":"Гантели и стул","level":"начальный","reps":"10–12","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Наклон и опора","Тяга к тазу","Контроль опускания"],"steps":["Сядьте на устойчивый стул, стопы на полу. Наклонитесь от таза, опустите гантели по сторонам голеней.","Подтяните локти к поясу без подъёма плеч к ушам.","Плавно опустите гантели, сохраняя наклон корпуса."],"cue":"Держите шею на одной линии со спиной.","easier":"Снимите часть дисков и наклонитесь совсем немного. Стопы устойчиво стоят на полу.","advanced":false},{"id":"back04","group":"back","title":"Супермен — короткий подъём","muscles":"Разгибатели спины · ягодицы","equipment":"Коврик","level":"средний","reps":"8–10","rest":45,"sets":2,"unit":"reps","unilateral":false,"phases":["Лягте на живот","Небольшой подъём","Плавное возвращение"],"steps":["Лягте на живот, вытяните руки вперёд, смотрите вниз.","Приподнимите противоположные руку и ногу на несколько сантиметров. Не запрокидывайте голову.","Верните конечности на коврик и смените сторону; избегайте сильного прогиба поясницы."],"cue":"Приподнимите противоположные руку и ногу на несколько сантиметров. Не запрокидывайте голову.","easier":"Оставьте руки и голову на коврике. Приподнимайте по одной ноге на пару сантиметров без прогиба.","advanced":false},{"id":"back05","group":"back","title":"Разведения гантелей в наклоне","muscles":"Задние дельты · верх спины","equipment":"Гантели","level":"средний","reps":"10–12","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Зафиксируйте наклон","Разведите руки","Опустите медленно"],"steps":["Слегка согните локти, удерживайте корпус неподвижным.","Разведите руки в стороны без поднятия плеч к ушам.","Медленно вернитесь; используйте очень лёгкие гантели."],"cue":"Разведите руки в стороны без поднятия плеч к ушам.","easier":"Уберите гантели и слегка согните локти. Разводите руки в небольшом диапазоне.","advanced":false},{"id":"back06","group":"back","title":"Подъём рук в W вместо face pull","muscles":"Ромбовидные · задние дельты","equipment":"Коврик","level":"начальный","reps":"10–12","rest":45,"sets":2,"unit":"reps","unilateral":false,"phases":["Лягте, руки в W","Сведите лопатки","Опустите руки"],"steps":["Лягте на живот, согните локти и разложите руки буквой W. Лоб можно положить на сложенное полотенце.","Мягко сведите лопатки и слегка приподнимите кисти и локти. Ноги остаются на коврике.","Плавно опустите руки, не поднимая подбородок."],"cue":"Движение маленькое; не нужно высоко отрывать грудь.","easier":"Оставьте руки на коврике и мягко сведите лопатки, не поднимая грудь.","advanced":false},{"id":"back07","group":"back","title":"Лопаточные отжимания","muscles":"Передняя зубчатая · стабилизаторы лопаток","equipment":"Коврик","level":"средний","reps":"10–12","rest":45,"sets":2,"unit":"reps","unilateral":false,"phases":["Упор с прямыми руками","Сведите лопатки","Оттолкните пол"],"steps":["Встаньте в упор на ладони и колени, выстройте корпус от коленей до головы. Локти прямые.","Не сгибая локти, мягко сведите лопатки: грудная клетка чуть опустится между плечами.","Оттолкните пол ладонями и разведите лопатки. Амплитуда небольшая, руки всё время прямые."],"cue":"Не сгибая локти, мягко сведите лопатки: грудная клетка чуть опустится между плечами.","easier":"Встаньте на четвереньки с коленями под тазом. Двигайте только лопатками, не сгибая локти.","advanced":false},{"id":"back08","group":"back","title":"Y-подъёмы лёжа","muscles":"Нижняя трапеция · задние дельты","equipment":"Коврик","level":"начальный","reps":"10–12","rest":45,"sets":2,"unit":"reps","unilateral":false,"phases":["Руки буквой Y","Поднимите кисти","Опустите руки"],"steps":["Лягте на живот и расположите прямые руки по диагонали вперёд буквой Y, большие пальцы вверх.","Слегка поднимите кисти и руки над ковриком, мягко направляя лопатки вниз. Шея продолжает линию спины.","Плавно опустите руки. Высота подъёма небольшая."],"cue":"Слегка поднимите кисти и руки над ковриком, мягко направляя лопатки вниз. Шея продолжает линию спины.","easier":"Поднимайте по одной руке на пару сантиметров. Вторую руку оставьте на коврике, лоб — на полотенце.","advanced":false},{"id":"back09","group":"back","title":"W-подъёмы лёжа","muscles":"Ромбовидные · трапеция","equipment":"Коврик","level":"начальный","reps":"10–12","rest":45,"sets":2,"unit":"reps","unilateral":false,"phases":["Руки буквой W","Поднимите предплечья","Верните на коврик"],"steps":["Лягте на живот, согните локти и разложите руки буквой W. Лоб можно положить на сложенное полотенце.","Мягко сведите лопатки и слегка приподнимите кисти и локти. Ноги остаются на коврике.","Плавно опустите руки, не поднимая подбородок."],"cue":"Движение маленькое; не нужно высоко отрывать грудь.","easier":"Оставьте локти и кисти на коврике, мягко направляя лопатки друг к другу. Лоб лежит на полотенце.","advanced":false},{"id":"back10","group":"back","title":"Тяга одной гантели без опоры","muscles":"Широчайшие · мышцы корпуса","equipment":"Гантель","level":"средний","reps":"8–12","rest":60,"sets":2,"unit":"reps","unilateral":true,"phases":["Наклон корпуса","Локоть к тазу","Опустите гантель"],"steps":["Поставьте ноги устойчиво и наклонитесь от таза. Держите гантель в одной опущенной руке, второй слегка коснитесь бедра.","Подтяните локоть к тазу без поворота корпуса.","Медленно опустите гантель, затем повторите другой рукой."],"cue":"Если трудно удержать спину, выберите тягу с опорой на стул.","easier":"Свободной рукой обопритесь на устойчивый стул, как в тяге гантели с опорой.","advanced":false},{"id":"back11","group":"back","title":"Лодка — удержание лёжа","muscles":"Разгибатели спины · ягодицы","equipment":"Коврик","level":"средний","reps":"15–20 с","rest":45,"sets":2,"unit":"seconds","unilateral":false,"phases":["Лягте ровно","Короткое удержание","Расслабьтесь"],"steps":["Лягте на живот, руки вдоль тела, взгляд в коврик.","Слегка приподнимите грудь и ноги на несколько сантиметров; удерживайте положение с ровным дыханием.","Плавно опуститесь полностью на коврик."],"cue":"Не запрокидывайте голову и не стремитесь подняться выше.","easier":"Оставьте ноги на полу и слегка поднимите только грудь на короткий выдох, затем расслабьтесь.","advanced":false},{"id":"back12","group":"back","title":"Наклон с контролем спины","muscles":"Разгибатели спины · задняя поверхность бедра","equipment":"Свой вес","level":"начальный","reps":"10–12","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Ровная стойка","Отведите таз назад","Выпрямитесь"],"steps":["Встаньте устойчиво, руки скрестите на груди и слегка согните колени.","Отведите таз назад и наклонитесь от тазобедренных суставов, сохраняя длинную спину.","Вернитесь в стойку, не отклоняясь назад."],"cue":"Упражнение выполняется без гантелей.","easier":"Положите ладони на таз и выполните небольшой наклон, отводя таз к стене позади себя.","advanced":false},{"id":"chest01","group":"chest","title":"Отжимания от стены","muscles":"Грудные · трицепс","equipment":"Стена","level":"начальный","reps":"8–12","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Примите упор","Согните локти","Оттолкнитесь"],"steps":["Встаньте лицом к стене, ладони поставьте на уровне груди чуть шире плеч. Отойдите стопами на удобное расстояние.","Плавно согните локти, направляя их по диагонали к рёбрам. Грудь приближается к стене, тело остаётся одной линией.","На выдохе оттолкнитесь ладонями и вернитесь в исходное положение."],"cue":"Не тянитесь к стене только головой и не прогибайтесь в пояснице.","easier":"Подойдите на полшага ближе к стене. Сгибайте локти неглубоко, сохраняя тело одной линией.","advanced":false},{"id":"chest02","group":"chest","title":"Отжимания с коленей","muscles":"Грудные · трицепс","equipment":"Коврик","level":"средний","reps":"6–10","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Примите упор","Согните локти","Оттолкнитесь"],"steps":["Поставьте ладони на коврик чуть шире плеч, колени оставьте на мягкой опоре. Корпус прямой от головы до коленей.","Плавно согните локти примерно под углом 30–45° к корпусу и опустите грудь.","Оттолкнитесь ладонями и вернитесь, не отводя таз к пяткам."],"cue":"Опускайтесь настолько, насколько можете сохранить линию корпуса.","easier":"Перенесите ладони на устойчивую высокую опору или выполняйте отжимания от стены.","advanced":false},{"id":"chest03","group":"chest","title":"Отжимания от устойчивой опоры","muscles":"Грудные · трицепс","equipment":"Опора","level":"начальный","reps":"8–12","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Примите упор","Согните локти","Оттолкнитесь"],"steps":["Поставьте ладони чуть шире плеч на неподвижную высокую опору. Отойдите стопами назад, выстройте тело в линию.","Согните локти, приближая грудь к опоре. Таз не провисает.","Выдохните и оттолкнитесь от опоры."],"cue":"Подойдёт закреплённая столешница; опора не должна скользить или опрокидываться.","easier":"Выберите более высокую неподвижную опору или перейдите к стене.","advanced":false},{"id":"chest04","group":"chest","title":"Жим гантелей на полу","muscles":"Грудные · трицепс","equipment":"Гантели и коврик","level":"начальный","reps":"10–12","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Подготовьте гантели","Выжмите вверх","Опустите под контролем"],"steps":["Лягте на спину, колени согнуты, стопы на полу. Гантели над локтями, верхняя часть рук мягко касается коврика.","На выдохе выжмите гантели над грудью, удерживая запястья ровно.","Плавно опустите локти до лёгкого касания пола, не ударяя ими."],"cue":"Локти идут по диагонали к корпусу, плечи не поднимаются к ушам.","easier":"Снимите часть дисков с обеих гантелей. Опускайте локти до мягкого касания пола.","advanced":false},{"id":"chest05","group":"chest","title":"Разведение гантелей на полу","muscles":"Грудные","equipment":"Гантели и коврик","level":"средний","reps":"10–12","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Руки над грудью","Мягко разведите","Сведите руки"],"steps":["Лягте на пол, держите локти слегка согнутыми.","Разведите руки до мягкого касания плечом пола.","Сведите гантели над грудью без изменения угла локтей."],"cue":"Разведите руки до мягкого касания плечом пола.","easier":"Сильнее согните локти и выполните жим гантелей на полу вместо широкого разведения.","advanced":false},{"id":"chest06","group":"chest","title":"Узкие отжимания с коленей","muscles":"Трицепс · грудные","equipment":"Коврик","level":"средний","reps":"6–8","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Примите упор","Согните локти","Оттолкнитесь"],"steps":["Примите упор на колени и ладони. Ладони на ширине плеч, тело прямое от головы до коленей.","Неглубоко согните локти, направляя их назад ближе к рёбрам.","Оттолкнитесь от пола, сохраняя положение таза."],"cue":"Узкая постановка не требует сводить ладони вплотную.","easier":"Выполняйте узкое отжимание от стены: ладони на ширине плеч, локти идут ближе к рёбрам.","advanced":false},{"id":"chest07","group":"chest","title":"Жим гантелей с нейтральным хватом","muscles":"Грудные · трицепс","equipment":"Гантели и коврик","level":"начальный","reps":"10–12","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Подготовьте гантели","Выжмите вверх","Опустите под контролем"],"steps":["Лягте на спину, стопы на полу. Держите гантели у груди ладонями друг к другу, локти близко к корпусу.","Выжмите гантели вверх над грудью без разворота кистей.","Плавно опустите локти на коврик, сохраняя нейтральный хват."],"cue":"Запястья остаются над локтями, гантели не ударяются друг о друга.","easier":"Возьмите более лёгкие гантели. Ладони смотрят друг на друга, локти опускаются на пол мягко.","advanced":false},{"id":"chest08","group":"chest","title":"Пуловер на полу","muscles":"Грудные · широчайшие","equipment":"Гантель и коврик","level":"средний","reps":"8–10","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Гантель над грудью","Отведите руки назад","Верните над грудью"],"steps":["Удерживайте одну лёгкую гантель двумя руками.","Плавно отведите руки за голову в небольшой амплитуде, рёбра не поднимайте.","Верните гантель над грудью. При дискомфорте в плече сократите движение."],"cue":"Плавно отведите руки за голову в небольшой амплитуде, рёбра не поднимайте.","easier":"Выполните движение без гантели и отводите руки назад только до сохранения спокойного положения поясницы.","advanced":false},{"id":"chest09","group":"chest","title":"Отжимания с ногами на опоре","muscles":"Грудные · плечи","equipment":"Низкая опора","level":"сложный","reps":"6–8","rest":75,"sets":2,"unit":"reps","unilateral":false,"phases":["Примите упор","Согните локти","Оттолкнитесь"],"steps":["Поставьте носки на низкую неподвижную опору, ладони — на пол чуть шире плеч. Выстройте тело в линию.","Согните локти по диагонали назад и опустите грудь без провисания таза.","Оттолкнитесь ладонями и вернитесь в упор."],"cue":"Этот вариант сложнее обычного отжимания: сначала освойте высокую опору под ладонями.","easier":"Поставьте стопы на пол, а ладони — на высокую устойчивую опору или стену.","advanced":true},{"id":"shoulders01","group":"shoulders","title":"Жим гантелей сидя","muscles":"Передние и средние дельты · трицепс","equipment":"Гантели и стул","level":"начальный","reps":"8–12","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Гантели у плеч","Поднимите руки","Верните к плечам"],"steps":["Сядьте на устойчивый стул, стопы на полу. Гантели у плеч, запястья над локтями, живот слегка напряжён.","Плавно выжмите гантели вверх в удобном диапазоне. Не отклоняйте корпус назад.","Верните гантели к плечам под контролем."],"cue":"Не пытайтесь поднять руки выше за счёт прогиба в пояснице.","easier":"Снимите часть дисков или сначала выжимайте пустые руки сидя. Поднимайте их только в удобном диапазоне.","advanced":false},{"id":"shoulders02","group":"shoulders","title":"Жим гантелей стоя","muscles":"Дельты · трицепс · кор","equipment":"Гантели","level":"средний","reps":"8–10","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Гантели у плеч","Поднимите руки","Верните к плечам"],"steps":["Встаньте на ширине таза, держите гантели у плеч, колени слегка мягкие.","Выжмите гантели вверх без толчка ногами и без прогиба в пояснице.","Медленно верните гантели к плечам."],"cue":"Рёбра остаются над тазом, дыхание свободное.","easier":"Сядьте на устойчивый стул и используйте более лёгкие гантели или пустые руки.","advanced":false},{"id":"shoulders03","group":"shoulders","title":"Подъём гантелей перед собой","muscles":"Передние дельты","equipment":"Гантели","level":"начальный","reps":"10–12","rest":45,"sets":2,"unit":"reps","unilateral":false,"phases":["Опустите руки","Поднимите до удобной высоты","Медленно опустите"],"steps":["Встаньте устойчиво, гантели перед бёдрами, локти слегка согнуты.","Поднимите руки вперёд до удобной высоты, не выше плеч, без раскачивания.","Медленно опустите гантели к бёдрам."],"cue":"Поднимайте руки вперёд, сохраняя плечи опущенными.","easier":"Поднимайте руки без гантелей, слегка согнув локти. Остановитесь ниже уровня плеч.","advanced":false},{"id":"shoulders04","group":"shoulders","title":"Разведения гантелей в стороны","muscles":"Средние дельты","equipment":"Гантели","level":"начальный","reps":"10–12","rest":45,"sets":2,"unit":"reps","unilateral":false,"phases":["Опустите руки","Поднимите до удобной высоты","Медленно опустите"],"steps":["Встаньте устойчиво, руки с гантелями по сторонам тела, локти слегка согнуты.","Поднимите руки в стороны до удобной высоты, не выше плеч.","Плавно опустите руки, не меняя угол локтей."],"cue":"Не пожимайте плечами, помогая гантелям подняться.","easier":"Уберите гантели, согните локти и поднимайте руки в стороны невысоко.","advanced":false},{"id":"shoulders05","group":"shoulders","title":"Разведения в наклоне на заднюю дельту","muscles":"Задние дельты","equipment":"Гантели","level":"средний","reps":"10–12","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Зафиксируйте наклон","Разведите руки","Опустите медленно"],"steps":["Слегка согните локти, удерживайте корпус неподвижным.","Разведите руки в стороны без поднятия плеч к ушам.","Медленно вернитесь; используйте очень лёгкие гантели."],"cue":"Разведите руки в стороны без поднятия плеч к ушам.","easier":"Выполните разведение без гантелей, слегка согнув локти и уменьшив подъём рук.","advanced":false},{"id":"shoulders06","group":"shoulders","title":"Низкая тяга гантелей к груди","muscles":"Средние дельты · трапеция","equipment":"Гантели","level":"средний","reps":"10–12","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Гантели у бёдер","Локти ниже плеч","Опустите гантели"],"steps":["Встаньте устойчиво, держите лёгкие гантели перед бёдрами, ладони к телу.","Поднимите гантели к нижним рёбрам, направляя локти в стороны. Локти остаются ниже плеч.","Медленно опустите гантели. При дискомфорте в плечах выберите подъём рук без веса."],"cue":"Поднимите гантели к нижним рёбрам, направляя локти в стороны. Локти остаются ниже плеч.","easier":"Уберите гантели и поднимайте согнутые руки немного в стороны. Локти остаются ниже плеч.","advanced":false},{"id":"shoulders07","group":"shoulders","title":"Круговые движения руками","muscles":"Дельты · стабилизаторы плеча","equipment":"Без веса","level":"начальный","reps":"8–10","rest":45,"sets":2,"unit":"reps","unilateral":false,"phases":["Руки в стороны ниже плеч","Маленький круг вперёд","Завершите круг"],"steps":["Встаньте устойчиво и разведите прямые руки в стороны до комфортной высоты, без гантелей.","Выполняйте маленькие плавные круги руками, не поднимая плечи к ушам.","Смените направление кругов, затем опустите руки. Не делайте резких махов."],"cue":"Выполняйте маленькие плавные круги руками, не поднимая плечи к ушам.","easier":"Опустите руки ниже уровня плеч и рисуйте кистями очень маленькие круги без веса.","advanced":false},{"id":"shoulders08","group":"shoulders","title":"Арнольд-жим сидя","muscles":"Передние и средние дельты","equipment":"Гантели и стул","level":"средний","reps":"8–10","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Ладони к себе","Разворот и жим","Верните к плечам"],"steps":["Сядьте с опорой спины, держите гантели перед плечами ладонями к себе.","Плавно выжимайте гантели вверх, разворачивая ладони вперёд. Не поднимайте плечи к ушам.","Опускайте гантели и поворачивайте ладони к себе. При дискомфорте выберите обычный жим."],"cue":"Плавно выжимайте гантели вверх, разворачивая ладони вперёд. Не поднимайте плечи к ушам.","easier":"Уберите разворот: выполните обычный жим сидя с более лёгкими гантелями.","advanced":false},{"id":"shoulders09","group":"shoulders","title":"Подъём одной руки с опорой","muscles":"Средняя дельта","equipment":"Гантель и опора","level":"средний","reps":"10–12","rest":45,"sets":2,"unit":"reps","unilateral":true,"phases":["Опустите руки","Поднимите до удобной высоты","Медленно опустите"],"steps":["Возьмитесь одной рукой за устойчивую опору. В другой руке лёгкая гантель, локоть слегка согнут.","Поднимите рабочую руку в сторону до комфортной высоты, максимум до уровня плеч. Не наклоняйте корпус.","Медленно опустите гантель, затем смените руку."],"cue":"Поднимите рабочую руку в сторону до комфортной высоты, максимум до уровня плеч. Не наклоняйте корпус.","easier":"Держитесь за опору, уберите гантель и поднимайте согнутую руку невысоко.","advanced":false},{"id":"shoulders10","group":"shoulders","title":"Обратные разведения лёжа","muscles":"Задние дельты · ромбовидные","equipment":"Коврик","level":"начальный","reps":"10–12","rest":45,"sets":2,"unit":"reps","unilateral":false,"phases":["Лягте, руки в стороны","Сведите лопатки","Опустите руки"],"steps":["Лягте на живот, разведите руки в стороны, локти слегка согнуты. Смотрите в коврик.","Слегка поднимите руки, мягко сводя лопатки. Грудь и таз сохраняют опору.","Опустите руки без рывка и не запрокидывайте голову."],"cue":"Слегка поднимите руки, мягко сводя лопатки. Грудь и таз сохраняют опору.","easier":"Оставьте руки на коврике и только мягко сведите лопатки. Лоб опирается на полотенце.","advanced":false},{"id":"shoulders11","group":"shoulders","title":"Жим одной гантели над головой","muscles":"Дельта · трицепс · стабилизаторы","equipment":"Гантель","level":"средний","reps":"8–10","rest":60,"sets":2,"unit":"reps","unilateral":true,"phases":["Гантель у плеча","Выжмите одной рукой","Верните к плечу"],"steps":["Встаньте устойчиво, одна гантель у плеча. Вторая рука свободно опущена.","Выжмите гантель вверх одной рукой, не наклоняя корпус и не прогибая поясницу.","Верните гантель к плечу, затем смените руку."],"cue":"Выжмите гантель вверх одной рукой, не наклоняя корпус и не прогибая поясницу.","easier":"Сядьте на стул и выполните жим одной пустой рукой, без наклона корпуса.","advanced":false},{"id":"arms01","group":"arms","title":"Сгибание рук стоя","muscles":"Бицепс","equipment":"Гантели","level":"начальный","reps":"10–12","rest":45,"sets":2,"unit":"reps","unilateral":false,"phases":["Руки опущены","Согните локти","Опустите гантели"],"steps":["Встаньте устойчиво, гантели в опущенных руках, ладони смотрят вперёд. Локти рядом с корпусом.","Согните локти и поднимите гантели без раскачивания тела.","Медленно разогните локти, сохраняя запястья ровными."],"cue":"Плечо остаётся на месте, двигается предплечье.","easier":"Сядьте на устойчивый стул и возьмите более лёгкие гантели. Локти остаются рядом с туловищем.","advanced":false},{"id":"arms02","group":"arms","title":"Сгибание рук сидя","muscles":"Бицепс","equipment":"Гантели и стул","level":"начальный","reps":"10–12","rest":45,"sets":2,"unit":"reps","unilateral":false,"phases":["Руки опущены","Согните локти","Опустите гантели"],"steps":["Сядьте на устойчивый стул, стопы на полу. Руки с гантелями опущены по сторонам, ладони вперёд.","Согните локти без наклона корпуса и подъёма плеч.","Плавно опустите гантели."],"cue":"Локти остаются рядом с туловищем.","easier":"Снимите часть дисков и сгибайте руки по очереди, оставляя плечи неподвижными.","advanced":false},{"id":"arms03","group":"arms","title":"Молотковые сгибания","muscles":"Бицепс · плечевая · предплечья","equipment":"Гантели","level":"начальный","reps":"10–12","rest":45,"sets":2,"unit":"reps","unilateral":false,"phases":["Руки опущены","Согните локти","Опустите гантели"],"steps":["Держите гантели по сторонам тела ладонями друг к другу. Локти рядом с корпусом.","Согните локти, сохраняя ладони обращёнными друг к другу.","Плавно разогните руки без разворота кистей."],"cue":"Запястья прямые, корпус не раскачивается.","easier":"Возьмите более лёгкие гантели и сгибайте руки по очереди. Ладони всё время смотрят друг на друга.","advanced":false},{"id":"arms04","group":"arms","title":"Концентрированное сгибание","muscles":"Бицепс","equipment":"Гантель и стул","level":"средний","reps":"10–12","rest":45,"sets":2,"unit":"reps","unilateral":true,"phases":["Руки опущены","Согните локти","Опустите гантели"],"steps":["Сядьте устойчиво, стопы шире таза. Уприте локоть рабочей руки во внутреннюю поверхность бедра.","Согните локоть и поднимите гантель без движения плечом или корпусом.","Медленно опустите гантель, затем смените руку."],"cue":"Согните локоть и поднимите гантель без движения плечом или корпусом.","easier":"Снимите часть дисков или сгибайте пустую руку, сохраняя локоть на бедре.","advanced":false},{"id":"arms05","group":"arms","title":"Разгибание рук за головой","muscles":"Трицепс","equipment":"Гантель и стул","level":"средний","reps":"10–12","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Гантель над головой","Согните локти","Разогните руки"],"steps":["Сядьте на устойчивый стул. Удерживайте одну гантель двумя руками над головой, предварительно проверив фиксаторы.","Согните локти и опустите гантель за голову в удобном диапазоне. Верхняя часть рук остаётся на месте.","Плавно разогните локти без прогиба в пояснице."],"cue":"Начните с очень лёгкой гантели; не направляйте её к шее.","easier":"Выполняйте разгибание без гантели. Если поднять руки неудобно, попробуйте разгибание руки в наклоне с опорой.","advanced":false},{"id":"arms06","group":"arms","title":"Разгибание руки в наклоне","muscles":"Трицепс","equipment":"Гантель и стул","level":"начальный","reps":"10–12","rest":45,"sets":2,"unit":"reps","unilateral":true,"phases":["Устойчивая опора","Разогните локоть","Верните предплечье"],"steps":["Обопритесь одной рукой на устойчивый стул и наклонитесь от таза. Прижмите верхнюю часть рабочей руки к боку, локоть согнут.","Разогните локоть назад, не поднимая и не раскачивая плечо.","Плавно согните локоть обратно. После повторов смените руку."],"cue":"Двигается только предплечье, запястье остаётся прямым.","easier":"Уберите гантель. С опорой второй рукой медленно разгибайте локоть, удерживая верхнюю часть руки вдоль корпуса.","advanced":false},{"id":"arms07","group":"arms","title":"Узкое отжимание от опоры","muscles":"Трицепс · грудные","equipment":"Стена или стол","level":"начальный","reps":"8–12","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Примите упор","Согните локти","Оттолкнитесь"],"steps":["Встаньте лицом к стене или высокой неподвижной опоре. Ладони на ширине плеч, тело прямое.","Сгибайте локти назад ближе к рёбрам, приближая грудь к опоре.","На выдохе оттолкнитесь и вернитесь в упор."],"cue":"Не сводите ладони так узко, чтобы заламывать запястья.","easier":"Выберите стену и подойдите ближе к ней. Ладони на ширине плеч, локти рядом с рёбрами.","advanced":false},{"id":"arms08","group":"arms","title":"Обратное отжимание от стула","muscles":"Трицепс","equipment":"Стул","level":"средний","reps":"6–8","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Руки на опоре","Неглубоко согните локти","Выпрямите руки"],"steps":["Придвиньте устойчивый стул к стене и держите таз близко к сиденью.","Согните локти совсем немного, не опуская плечи ниже локтей.","Поднимитесь; при давлении в плече замените разгибанием руки с гантелью."],"cue":"Согните локти совсем немного, не опуская плечи ниже локтей.","easier":"Вместо отжимания от стула выполните узкое отжимание от стены, направляя локти назад к рёбрам.","advanced":false},{"id":"arms09","group":"arms","title":"Французский жим на полу","muscles":"Трицепс","equipment":"Гантели и коврик","level":"средний","reps":"10–12","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Руки над грудью","Согните только локти","Разогните локти"],"steps":["Лягте на спину, стопы на полу. Поднимите гантели над плечами, верхняя часть рук вертикальна.","Сгибайте только локти, плавно опуская гантели по сторонам головы. Плечи остаются неподвижны.","Разогните локти и верните гантели над плечами. Не разводите локти широко."],"cue":"Сгибайте только локти, плавно опуская гантели по сторонам головы. Плечи остаются неподвижны.","easier":"Выполняйте движение без гантелей, сгибая только локти. Верхняя часть рук направлена к потолку.","advanced":false},{"id":"arms10","group":"arms","title":"Сгибание с супинацией","muscles":"Бицепс · предплечья","equipment":"Гантели","level":"начальный","reps":"10–12","rest":45,"sets":2,"unit":"reps","unilateral":false,"phases":["Руки опущены","Согните локти","Опустите гантели"],"steps":["Встаньте с гантелями в опущенных руках, ладони обращены к бёдрам.","Сгибая локти, плавно разверните ладони вверх. Верхняя часть рук остаётся возле корпуса.","Медленно опустите гантели, возвращая ладони к бёдрам."],"cue":"Разворот плавный, запястья не сгибаются.","easier":"Уберите разворот кистей: сгибайте руки с более лёгкими гантелями ладонями вперёд.","advanced":false},{"id":"arms11","group":"arms","title":"Алмазные отжимания с коленей","muscles":"Трицепс · грудные","equipment":"Коврик","level":"сложный","reps":"6–8","rest":75,"sets":2,"unit":"reps","unilateral":false,"phases":["Примите упор","Согните локти","Оттолкнитесь"],"steps":["Примите упор на колени. Под грудью приблизьте большие и указательные пальцы, не создавая дискомфорта в кистях.","Неглубоко согните локти, направляя их назад, а не широко в стороны.","Оттолкнитесь от пола, сохраняя корпус прямым от головы до коленей."],"cue":"Если кистям неудобно, расставьте ладони на ширину плеч или выберите стену.","easier":"Расставьте ладони на ширину плеч и выполняйте отжимание от стены.","advanced":true},{"id":"arms12","group":"arms","title":"Разгибание одной руки над головой","muscles":"Трицепс","equipment":"Гантель","level":"средний","reps":"8–10","rest":60,"sets":2,"unit":"reps","unilateral":true,"phases":["Гантель над головой","Согните рабочий локоть","Разогните локоть"],"steps":["Встаньте устойчиво. Поднимите одну гантель одной рукой над головой; второй рукой поддержите плечо.","Согните рабочий локоть, опуская гантель за голову. Плечо остаётся направленным вверх.","Разогните локоть без прогиба поясницы. Затем смените руку."],"cue":"Согните рабочий локоть, опуская гантель за голову. Плечо остаётся направленным вверх.","easier":"Начните без гантели. Если поднятая рука неудобна, выполните разгибание локтя в наклоне с опорой.","advanced":false},{"id":"arms13","group":"arms","title":"Изометрическое удержание гантелей","muscles":"Бицепс · мышцы хвата","equipment":"Гантели","level":"начальный","reps":"15–20 с","rest":45,"sets":2,"unit":"seconds","unilateral":false,"phases":["Гантели внизу","Удержание под углом 90°","Плавно опустите"],"steps":["Встаньте устойчиво с гантелями в опущенных руках.","Согните локти примерно до прямого угла и удерживайте гантели неподвижно. Продолжайте дышать.","Плавно опустите руки, когда удержание закончится."],"cue":"Не прижимайте гантели к туловищу и не поднимайте плечи.","easier":"Возьмите более лёгкие гантели и удерживайте локти согнутыми 5–10 секунд, затем опустите руки.","advanced":false},{"id":"core01","group":"core","title":"Планка на прямых руках","muscles":"Мышцы живота · стабилизаторы","equipment":"Коврик","level":"средний","reps":"20–30 с","rest":60,"sets":2,"unit":"seconds","unilateral":false,"phases":["Установите опору","Удерживайте положение","Плавно выйдите"],"steps":["Из упора на ладони и колени поставьте ладони под плечами и по очереди выпрямите ноги.","Удерживайте прямую линию от головы до пяток, слегка напрягая живот. Дышите ровно.","Плавно верните колени на коврик и расслабьтесь."],"cue":"Не допускайте провисания таза; закончите удержание до потери контроля.","easier":"Поставьте ладони на устойчивую высокую опору или стену и удерживайте тело одной линией.","advanced":false},{"id":"core02","group":"core","title":"Планка на предплечьях","muscles":"Прямая и поперечная мышцы живота","equipment":"Коврик","level":"средний","reps":"20–30 с","rest":60,"sets":2,"unit":"seconds","unilateral":false,"phases":["Установите опору","Удерживайте положение","Плавно выйдите"],"steps":["Опуститесь на предплечья, локти под плечами. Из опоры на колени выпрямите ноги.","Удерживайте корпус одной линией, не задерживая дыхание.","Плавно опустите колени на коврик и расслабьтесь."],"cue":"Шея продолжает спину, поясница не провисает.","easier":"Оставьте колени на коврике. Удерживайте прямую линию от головы до коленей 5–10 секунд.","advanced":false},{"id":"core03","group":"core","title":"Боковая планка","muscles":"Косые мышцы живота · ягодицы","equipment":"Коврик","level":"средний","reps":"15–20 с","rest":60,"sets":2,"unit":"seconds","unilateral":true,"phases":["Боковая опора с колена","Поднимите и удержите таз","Опуститесь на коврик"],"steps":["Лягте на бок, согните колени. Обопритесь на предплечье, локоть точно под плечом.","Поднимите таз, опираясь на предплечье и нижнее колено. Удерживайте линию от головы до коленей с ровным дыханием.","Медленно опустите таз. Затем выполните другую сторону."],"cue":"На картинке вариант с согнутыми коленями. Не заваливайтесь вперёд или назад.","easier":"Оставьте оба колена согнутыми на коврике и поднимите таз совсем немного на 5–10 секунд.","advanced":false},{"id":"core04","group":"core","title":"Короткие скручивания","muscles":"Прямая мышца живота","equipment":"Коврик","level":"начальный","reps":"10–12","rest":45,"sets":2,"unit":"reps","unilateral":false,"phases":["Лягте на коврик","Короткое скручивание","Опустите плечи"],"steps":["Лягте на спину, согните колени, стопы на полу. Голова и плечи лежат на коврике, руки направлены к бёдрам.","На выдохе слегка приподнимите лопатки, потянувшись руками к коленям. Не садитесь полностью.","Медленно опустите плечи и голову на коврик."],"cue":"Не тяните подбородок к груди; движение короткое и спокойное.","easier":"Оставьте голову и плечи на коврике. На выдохе мягко напрягайте живот, затем расслабляйтесь.","advanced":false},{"id":"core05","group":"core","title":"Велосипед под контролем","muscles":"Косые мышцы · прямая мышца живота","equipment":"Коврик","level":"средний","reps":"8–10","rest":45,"sets":2,"unit":"reps","unilateral":true,"phases":["Колени над тазом","Поворот к противоположному колену","Вернитесь и смените сторону"],"steps":["Лягте на спину, колени над тазом, пальцы легко касаются головы, локти раскрыты.","Поверните грудную клетку к противоположному колену, другую ногу вытяните в посильной амплитуде.","Вернитесь в центр и смените сторону. Не тяните голову руками и не увеличивайте прогиб."],"cue":"Поверните грудную клетку к противоположному колену, другую ногу вытяните в посильной амплитуде.","easier":"Оставьте голову на коврике и поочерёдно выпрямляйте ноги, скользя пятками по полу, без скручивания.","advanced":false,"alternating":true},{"id":"core06","group":"core","title":"Мёртвый жук","muscles":"Глубокие мышцы живота · стабилизаторы","equipment":"Коврик","level":"начальный","reps":"8–10","rest":45,"sets":2,"unit":"reps","unilateral":true,"phases":["Колени над тазом","Вытяните противоположные конечности","Вернитесь под контролем"],"steps":["Лягте на спину, голову оставьте на коврике. Руки направлены к потолку, колени согнуты под прямым углом над тазом.","Медленно отведите одну руку за голову и выпрямите противоположную ногу. Не усиливайте прогиб в пояснице.","Вернитесь в исходное положение и повторите другой диагональю. Считайте повторы на каждую сторону."],"cue":"Рука и нога работают по диагонали: правая рука с левой ногой, затем наоборот.","easier":"Оставьте голову и руки на коврике. Поочерёдно скользите пяткой вперёд по полу и возвращайте ногу.","advanced":false,"alternating":true},{"id":"core07","group":"core","title":"Подъём согнутых ног лёжа","muscles":"Прямая мышца живота · сгибатели бедра","equipment":"Коврик","level":"средний","reps":"8–10","rest":60,"sets":2,"unit":"reps","unilateral":false,"phases":["Ноги согнуты","Поднимите ноги","Опустите до контроля"],"steps":["Лягте на спину, колени согнуты, обе стопы на полу. Руки лежат вдоль тела.","Поднимите согнутые ноги, пока колени не окажутся над тазом. Поясница остаётся спокойной.","Плавно верните стопы на пол, не выпрямляя ноги низко над ковриком."],"cue":"Если поясница прогибается, поднимайте ноги по одной.","easier":"Поднимайте по одной согнутой ноге, оставляя вторую стопу на полу. Не меняйте положение поясницы.","advanced":false},{"id":"core08","group":"core","title":"Русские повороты без веса","muscles":"Косые мышцы живота","equipment":"Коврик","level":"средний","reps":"8–10","rest":45,"sets":2,"unit":"reps","unilateral":false,"phases":["Устойчивая опора","Мягкий поворот","Вернитесь в центр"],"steps":["Сядьте на коврик, колени согнуты, стопы на полу. Удлините спину и немного отклонитесь назад.","Сложите руки перед грудью и поверните грудную клетку в небольшой амплитуде; таз остаётся устойчив.","Вернитесь в центр и повернитесь в другую сторону, сохраняя стопы на полу."],"cue":"Сложите руки перед грудью и поверните грудную клетку в небольшой амплитуде; таз остаётся устойчив.","easier":"Сядьте вертикальнее и поворачивайте грудную клетку совсем немного. Обе стопы остаются на полу.","advanced":false},{"id":"core09","group":"core","title":"Медленный альпинист","muscles":"Мышцы живота · плечевой пояс","equipment":"Коврик","level":"средний","reps":"10–12","rest":45,"sets":2,"unit":"reps","unilateral":true,"phases":["Упор ладонями","Подтяните колено","Смените ногу"],"steps":["Поставьте ладони под плечами, держите таз ровно.","Медленно подтяните одно колено, не прыгая.","Верните ногу и смените сторону; можно выполнять у стены."],"cue":"Медленно подтяните одно колено, не прыгая.","easier":"Обопритесь ладонями о стену или высокую устойчивую поверхность и медленно поднимайте по одному колену.","advanced":false,"alternating":true},{"id":"core10","group":"core","title":"Лодочка на спине — облегчённая","muscles":"Глубокие мышцы живота","equipment":"Коврик","level":"средний","reps":"15–20 с","rest":60,"sets":2,"unit":"seconds","unilateral":false,"phases":["Лягте, колени согнуты","Короткое удержание корпуса","Плавно расслабьтесь"],"steps":["Лягте на спину, колени согнуты над тазом, руки вдоль тела. Поясница спокойно прижата к коврику.","Слегка поднимите лопатки и потянитесь руками к коленям. Ноги оставьте согнутыми, продолжайте дышать.","Завершите короткое удержание до потери положения поясницы и плавно опустите плечи."],"cue":"Слегка поднимите лопатки и потянитесь руками к коленям. Ноги оставьте согнутыми, продолжайте дышать.","easier":"Оставьте голову и плечи на коврике, стопы на полу. На выдохе мягко напрягите живот и продолжайте дышать.","advanced":false}];
export const byId=Object.fromEntries(exercises.map(e=>[e.id,e]));
